<template>
 <div class="sale-page">
  <PageHead title="权益包选购"><el-button v-if="returnTo" @click="router.push(returnTo)">返回来源</el-button><el-button @click="newSale">新建自由组合</el-button><el-select :model-value="work.record.id||undefined" placeholder="查看已保存清单" aria-label="已保存清单" class="saved-picker" @change="loadRecord"><el-option v-for="s in store.data.benefitSalesLists||[]" :key="s.id" :value="s.id" :label="`${s.status==='confirmed'?'已确认':'草稿'} · ${s.updatedAt.slice(0,16)} · ${s.lines.length} 件商品`"/></el-select><el-button v-if="store.canRoute({path:'/benefits/manage'})" @click="router.push('/benefits/manage')">管理权益包</el-button></PageHead>
  <el-alert v-if="error" :title="error" type="warning" :closable="false" data-sale-error/>
 <section v-if="readonly" class="panel" data-confirmed-sale><h2>已确认清单 · 历史只读</h2><p>{{work.record.snapshot?.confirmedAt}} · {{work.record.snapshot?.groupName||'自由组合'}}</p><p>本次使用设备：{{snapshotDevice}}</p><el-table :data="work.record.snapshot?.lines||[]"><el-table-column prop="name" label="商品"/><el-table-column prop="spec" label="实际规格"/><el-table-column prop="quantity" label="数量"/><el-table-column label="单价"><template #default="{row}">{{money(row.unitPriceCents)}}</template></el-table-column><el-table-column label="当时适用依据"><template #default="{row}"><details><summary>{{row.evidence?.length??row.declarations.length}} 条依据</summary><CompatibilityEvidence v-if="row.evidence" :evidence="row.evidence"/><p v-for="d in row.evidence?[]:row.declarations" :key="d.id">{{d.source||d.note||'历史正式适用关系'}} · {{d.verification==='confirmed'?'已核验':'待核验'}}</p></details></template></el-table-column></el-table><h3>合计 {{money(work.record.snapshot?.totalCents??0)}}</h3><el-button @click="copyConfirmed">复制为新草稿并按当前资料核对</el-button></section>
 <div v-if="!readonly" class="selection-workbench">
  <aside class="panel device-panel">
   <div class="section-heading"><h2>选择手机</h2><small>{{phoneRows.length}} 个规格</small></div>
   <el-input v-model="phoneSearch" clearable placeholder="搜索型号、规格或编码" aria-label="搜索手机"/>
   <el-select v-if="hostTypes.length>1" v-model="phoneType" aria-label="设备类型" class="device-filter"><el-option label="全部设备" value=""/><el-option v-for="t in hostTypes" :key="t.id" :label="t.name" :value="t.id"/></el-select>
   <div class="device-list"><section v-for="group in phoneGroups" :key="group.id" class="phone-model"><h3>{{group.name}}</h3><button v-for="phone in group.skus" :key="phone.id" type="button" class="phone-option" :class="{selected:deviceKey(work.record.scope.device)===`sku:${phone.id}`}" :aria-pressed="deviceKey(work.record.scope.device)===`sku:${phone.id}`" :disabled="busy" :data-phone-sku="phone.id" @click="selectDevice(`sku:${phone.id}`)"><span class="phone-icon"><el-icon><Iphone/></el-icon></span><span class="phone-copy"><strong>{{phone.spec||'标准规格'}}</strong><small>{{phone.code}}</small></span><el-icon v-if="deviceKey(work.record.scope.device)===`sku:${phone.id}`" class="selected-icon"><CircleCheckFilled/></el-icon></button></section><p v-if="!phoneRows.length" class="empty-note">没有找到手机，请调整搜索或设备类型。</p></div>
   <details class="existing-device"><summary>客户已有手机 / 其他设备</summary><el-select :model-value="deviceKey(work.record.scope.device)" filterable clearable :disabled="busy" placeholder="选择已有手机型号" aria-label="本次使用设备" @change="selectDevice(String($event||''))"><el-option-group label="实际设备规格"><el-option v-for="d in devices.skus" :key="d.id" :value="`sku:${d.id}`" :label="`${d.name} · ${d.spec}`"/></el-option-group><el-option-group label="客户已有手机型号"><el-option v-for="m in devices.models" :key="m.key" :value="`model:${m.key}`" :label="m.label"/></el-option-group></el-select><p class="muted">只选型号时，资料不足的配件不会列为可选。</p></details>
  </aside>
  <main class="selection-main">
   <section class="panel current-device">
    <div class="current-heading"><span class="device-emblem"><el-icon><Iphone/></el-icon></span><div class="current-copy"><small>本次使用手机</small><h2>{{currentDevice.name}}</h2><p v-if="currentDevice.spec">{{currentDevice.spec}}</p></div><el-button v-if="deviceCandidate" type="primary" plain :disabled="busy" :data-sale-add="deviceCandidate.id" :data-sale-candidate="deviceCandidate.id" @click="add(deviceCandidate.id)">加入手机</el-button></div>
    <p class="muted device-hint">{{work.record.scope.device?'手机仅用于匹配配件，不会自动加入清单。':'从左侧选择具体手机规格，即可开始选配。'}}</p>
    <p v-if="query.device&&query.device.status!=='resolved'" class="empty-note">当前设备资料不足，请选择其他手机，或由管理员核对资料。</p>
    <div v-if="work.record.scope.device" class="bundle-options"><strong>{{work.record.scope.mode==='group'?sourceName:'自由选配'}}</strong><el-button v-for="g in relatedGroups.length>1?relatedGroups:relatedGroups.filter(g=>g.id!==work.record.scope.groupId)" :key="g.id" size="small" :type="g.id===work.record.scope.groupId?'primary':'default'" :plain="g.id!==work.record.scope.groupId" :disabled="busy" @click="selectGroup(g.id)">{{g.name}}</el-button><el-button v-if="work.record.scope.mode==='group'" size="small" :disabled="busy" @click="changeMode('free')">自由选配</el-button></div>
    <div class="tags"><span>本次范围</span><span v-for="id in work.record.scope.productTypeIds" :key="id" class="scope-tag">{{typeName(id)}}</span></div>
    <details class="scope-tools"><summary>调整选配范围</summary><div class="scope-row"><el-radio-group :model-value="work.record.scope.mode" :disabled="busy" aria-label="选购方式" @change="changeMode(String($event))"><el-radio-button value="free">自由组合</el-radio-button><el-radio-button value="group" :disabled="!store.can('product:type-bundle:read')">按权益包选购</el-radio-button></el-radio-group><template v-if="work.record.scope.mode==='group'"><el-select :model-value="work.record.scope.groupId" :disabled="busy" placeholder="选择启用的权益包" aria-label="选择权益包" @change="selectGroup"><el-option v-for="g in enabledGroups" :key="g.id" :value="g.id" :label="g.name"/></el-select><el-button v-if="work.record.scope.groupId" :disabled="busy" @click="selectGroup(work.record.scope.groupId)">采用最新配置</el-button></template><el-button v-else :disabled="busy" @click="openTypes">选择分类与参与类型</el-button></div></details>
   </section>
   <section class="panel accessory-panel"><div class="section-heading"><h2>配套商品</h2><el-input v-model="search" clearable placeholder="搜索配件" aria-label="搜索可选商品"/></div><p v-if="!work.record.scope.device" class="empty-note">选中手机后，这里会显示可用的配件。</p><template v-else><section v-for="g in accessoryGroups" :key="g.id" class="type-group" :data-accessory-group="g.id"><h3>{{g.name}}<small>{{g.candidates.length}} 款可选</small></h3><p v-if="!g.candidates.length" class="empty-note">{{g.empty==='条件待核验'?'部分商品资料不足，暂不可选':'当前没有可选商品'}}</p><p v-else-if="!filtered(g.candidates).length" class="empty-note">没有匹配的商品</p><div class="candidate-grid"><article v-for="c in filtered(g.candidates)" :key="c.id" class="candidate" :data-sale-candidate="c.id"><span class="accessory-icon"><el-icon><Goods/></el-icon></span><div class="candidate-copy"><strong>{{c.name}}</strong><p>{{compactSpec(c.id)||c.code}}</p><small v-if="selectedQuantity(c.id)" class="quantity-note">已选 {{selectedQuantity(c.id)}} 件</small><details v-if="c.match?.evidence?.length||store.can('product:compatibility:read')" class="evidence-details"><summary>适用详情</summary><CompatibilityEvidence v-if="c.match?.evidence?.length" :evidence="c.match.evidence"/><el-button v-if="store.can('product:compatibility:read')" link @click="maintain(c.id)">适用资料</el-button></details></div><el-button type="primary" plain circle :disabled="busy" :data-sale-add="c.id" :aria-label="`添加 ${c.name}`" @click="add(c.id)">＋</el-button></article></div></section></template><details v-if="store.can('product:compatibility:update')||store.can('product:compatibility:create')" class="diagnostics"><summary>为什么没有这个商品</summary><div v-for="g in query.groups" :key="g.id"><p v-for="d in g.diagnostics" :key="d.id">{{d.name}}：{{d.reason}} <el-button link @click="maintain(d.id)">查看适用资料</el-button></p></div></details></section>
   <section class="panel cart"><div class="section-heading"><h2>本次清单</h2><small>{{selectedCount}} 件商品</small></div><p v-if="!work.record.lines.length" class="empty-note">点击商品右侧的 ＋ 加入清单。</p><article v-for="l in work.record.lines" :key="l.skuId" class="line" :data-sale-line="l.skuId"><div class="line-name"><strong>{{saleLabel(store.data,l.skuId).name}}</strong><p>{{compactSpec(l.skuId)}}</p><p v-if="lineIssues.find(i=>i.skuId===l.skuId)" class="line-warning">{{lineIssues.find(i=>i.skuId===l.skuId)!.reason}}</p></div><label>数量<el-input-number v-model="l.quantity" :min="1" :max="100000" :precision="0" :disabled="busy" :aria-label="`数量 ${l.skuId}`"/></label><label>单价（元）<el-input v-model="work.prices[l.skuId]" placeholder="未报价" :disabled="busy" :aria-label="`报价 ${l.skuId}`"/></label><div class="line-total"><small>行金额</small><strong>{{lineAmount(l)}}</strong><el-button link type="danger" :disabled="busy" @click="remove(l.skuId)">移除</el-button></div></article></section>
   <footer class="sale-summary"><div><span>已选 {{selectedCount}} 件</span><strong>{{amount.complete?'合计':'已报价小计'}} {{money(amount.cents)}}</strong><small v-if="!amount.complete">未报价商品待补充 · 0 元表示免费</small></div><div class="summary-actions"><el-button :disabled="busy||!canSave" :loading="busy" data-save-sale @click="save('draft')">保存草稿</el-button><el-button type="primary" :disabled="busy||!canSave||!store.can('product:bundle-sale:confirm')" data-confirm-sale @click="save('confirmed')">确认清单</el-button></div></footer>
  </main>
 </div>
 <el-dialog v-model="typesOpen" title="本次参与的产品类型" width="min(900px,95vw)" :close-on-click-modal="false"><el-select v-model="pendingScope.categoryId" filterable placeholder="选择分类" aria-label="自由组合分类"><el-option v-for="c in store.data.categories" :key="c.id" :value="c.id" :label="categoryPathLabel(store.data.categories,c.id)"/></el-select><TypeSetPicker v-model="pendingScope.productTypeIds" :data="store.data" :category-id="pendingScope.categoryId"/><template #footer><el-button @click="typesOpen=false">取消</el-button><el-button type="primary" :disabled="busy" data-apply-types @click="applyTypes">应用本次类型</el-button></template></el-dialog>
 </div>
</template>
<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {Iphone,Goods,CircleCheckFilled} from '@element-plus/icons-vue'
import {compatibilityFamilyTypeId} from '../domain/deviceResolution'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate,type LocationQuery} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import CompatibilityEvidence from '../components/compatibility/CompatibilityEvidence.vue'
import PageHead from '../components/PageHead.vue'
import TypeSetPicker from '../components/benefit-sales/TypeSetPicker.vue'
import {workingSales,emptySale,emptyScope,type WorkingSale} from '../components/benefit-sales/working'
import {useCatalogStore} from '../stores/catalog'
import {saleQuery,saleLabel,deviceOptions,deviceKey,deviceFromKey,typesProblem,typeProblem} from '../domain/benefitSales/query'
import {copy,priceCents,total} from '../domain/benefitSales/commands'
import type {SaleScope,SaleLine,BenefitSale} from '../domain/benefitSales/types'
import {categoryPathLabel} from '../domain/categoryTree'
import {compatibilityReturnLocation} from '../domain/compatibilityNavigation'
const store=useCatalogStore(),route=useRoute(),router=useRouter(),actor=computed(()=>`${store.activeUserId}:${store.previewUserId}`)
const work=ref<WorkingSale>(copy(workingSales.get(actor.value)||emptySale())),error=ref(''),busy=ref(false),search=ref(''),typesOpen=ref(false),pendingScope=ref(emptyScope())
let internal=false,leavingForMaintenance=false
const stamp=()=>JSON.stringify([work.value.record,work.value.prices]),dirty=()=>work.value.saved!==stamp()&&work.value.record.status!=='confirmed'&&(!!work.value.record.id||work.value.record.lines.length>0||JSON.stringify(work.value.record.scope)!==JSON.stringify(emptyScope()))
const readonly=computed(()=>work.value.record.status==='confirmed'),returnTo=computed(()=>compatibilityReturnLocation(route.query.returnTo)),enabledGroups=computed(()=>(store.data.benefitTypeGroups||[]).filter(g=>g.enabled).slice().sort((a,b)=>a.sort-b.sort||a.name.localeCompare(b.name))),devices=computed(()=>deviceOptions(store.data))
const sourceName=computed(()=>store.data.benefitTypeGroups?.find(g=>g.id===work.value.record.scope.groupId)?.name||'原权益包已停用或不可查看')
const query=computed(()=>saleQuery(store.data,work.value.record.scope)),lineIssues=computed(()=>work.value.record.lines.filter(l=>!query.value.candidates.some(c=>c.id===l.skuId)).map(l=>({skuId:l.skuId,reason:query.value.groups.flatMap(g=>g.diagnostics).find(d=>d.id===l.skuId)?.reason||'不在当前类型范围内'})))
const pricedLines=computed(()=>work.value.record.lines.map(l=>({...l,unitPriceCents:priceCents(work.value.prices[l.skuId]||'')??null}))),amount=computed(()=>total(pricedLines.value)),canSave=computed(()=>store.can(`product:bundle-sale:${work.value.record.id?'update':'create'}`))
const snapshotDevice=computed(()=>work.value.record.snapshot?.device?.host?.steps.map(s=>s.valueId).join(' · ')||'独立购买，无配套设备')
const money=(n:number|null)=>n===null?'未报价':`¥${(n/100).toFixed(2)}`,typeName=(id:string)=>store.data.productTypes.find(t=>t.id===id)?.name||'类型已失效'
const phoneSearch=ref(''),phoneType=ref(store.data.productTypes.some(t=>t.id==='pt-phone')?'pt-phone':'')
const hostTypes=computed(()=>store.data.productTypes.filter(t=>t.catalogRole==='host'&&t.status==='enabled'))
function compactSpec(id:string){const sku=store.data.skus.find(s=>s.id===id);if(!sku)return '';const host=store.data.productTypes.find(t=>t.id===compatibilityFamilyTypeId(store.data,sku.familyId))?.catalogRole==='host';return Object.entries(sku.variantAttrs).filter(([key,value])=>value&&(!host||['容量','颜色'].includes(store.data.params.find(p=>p.id===key)?.name||key))).map(([,value])=>value).join(' · ')}
const phoneRows=computed(()=>devices.value.skus.filter(s=>{const sku=store.data.skus.find(x=>x.id===s.id)!;return (!phoneType.value||compatibilityFamilyTypeId(store.data,sku.familyId)===phoneType.value)&&`${s.name} ${s.spec} ${s.code}`.toLowerCase().includes(phoneSearch.value.trim().toLowerCase())}).map(s=>({...s,spec:compactSpec(s.id)})))
const phoneGroups=computed(()=>{const groups=new Map<string,{id:string;name:string;skus:typeof phoneRows.value}>();for(const row of phoneRows.value){const sku=store.data.skus.find(s=>s.id===row.id)!,family=store.data.families.find(f=>f.id===sku.familyId)!;let group=groups.get(family.id);if(!group){group={id:family.id,name:family.name,skus:[]};groups.set(family.id,group)}group.skus.push(row)}return [...groups.values()]})
const currentDevice=computed(()=>{const device=work.value.record.scope.device;if(device?.kind==='sku')return {name:saleLabel(store.data,device.skuId).name,spec:compactSpec(device.skuId)};if(device?.kind==='model')return {name:devices.value.models.find(m=>m.key===device.key)?.label||'请重新选择手机',spec:'客户已有手机'};return {name:'尚未选择手机',spec:''}})
function discovery(device:SaleScope['device']){return saleQuery(store.data,{...emptyScope(),device,productTypeIds:store.data.productTypes.filter(t=>['host','accessory'].includes(t.catalogRole||'')&&!typeProblem(store.data,t.id)).map(t=>t.id)})}
function relevantGroups(result:ReturnType<typeof saleQuery>){const types=new Set(result.groups.filter(g=>g.candidates.length).map(g=>g.id));if(result.device?.host)types.add(result.device.host.productTypeId);return enabledGroups.value.filter(g=>g.productTypeIds.some(id=>types.has(id)))}
const discovered=computed(()=>work.value.record.scope.device?discovery(work.value.record.scope.device):null),relatedGroups=computed(()=>discovered.value?relevantGroups(discovered.value):[])
function initialScope(next:SaleScope){if(!next.device||next.productTypeIds.length||next.mode==='group')return next;const result=discovery(next.device),group=relevantGroups(result)[0];if(group)return {...next,mode:'group' as const,groupId:group.id,categoryId:group.categoryId,productTypeIds:[...group.productTypeIds]};const ids=result.groups.filter(g=>g.candidates.length).map(g=>g.id);return {...next,categoryId:store.data.productTypes.find(t=>t.id===result.device?.host?.productTypeId)?.categoryId||'',productTypeIds:ids}}
const accessoryGroups=computed(()=>query.value.groups.filter(g=>store.data.productTypes.find(t=>t.id===g.id)?.catalogRole!=='host'))
const deviceCandidate=computed(()=>{const device=work.value.record.scope.device;return device?.kind==='sku'?query.value.candidates.find(c=>c.id===device.skuId):undefined})
const selectedCount=computed(()=>work.value.record.lines.reduce((sum,l)=>sum+l.quantity,0)),selectedQuantity=(id:string)=>work.value.record.lines.find(l=>l.skuId===id)?.quantity||0
function filtered<T extends {name:string;spec:string;code:string}>(rows:T[]){const s=search.value.trim().toLowerCase();return rows.filter(r=>`${r.name} ${r.spec} ${r.code}`.toLowerCase().includes(s))}
function lineAmount(l:SaleLine){const n=priceCents(work.value.prices[l.skuId]||'');return n===undefined?'报价无效':n===null?'未报价':money(n*l.quantity)}
function remove(id:string){work.value.record.lines=work.value.record.lines.filter(l=>l.skuId!==id);delete work.value.prices[id]}
function add(id:string){if(busy.value||readonly.value)return;const latest=saleQuery(store.data,work.value.record.scope);if(!latest.candidates.some(c=>c.id===id)){error.value='商品资料已变化，请核对当前候选';return}const line=work.value.record.lines.find(l=>l.skuId===id);if(line){if(line.quantity<100000)line.quantity++}else{work.value.record.lines.push({skuId:id,quantity:1,unitPriceCents:null});work.value.prices[id]=''}}
async function syncUrl(){internal=true;try{await router.replace({path:route.path,query:{...route.query,model:undefined,version:undefined,node:undefined,deviceModel:undefined,group:work.value.record.scope.mode==='group'?work.value.record.scope.groupId:undefined,device:deviceKey(work.value.record.scope.device)||undefined,sale:work.value.record.id||undefined}})}finally{internal=false}}
async function switchScope(next:SaleScope,updateUrl=true){if(busy.value)return false;busy.value=true;try{const fresh=saleQuery(store.data,next),keep=new Set(fresh.candidates.map(c=>c.id)),removed=work.value.record.lines.filter(l=>!keep.has(l.skuId));if(removed.length){await ElMessageBox.confirm(['保留商品（数量和报价不变）：'+(work.value.record.lines.filter(l=>keep.has(l.skuId)).map(l=>saleLabel(store.data,l.skuId).name).join('、')||'无'),'移除商品：'+removed.map(l=>`${saleLabel(store.data,l.skuId).name}：${fresh.groups.flatMap(g=>g.diagnostics).find(d=>d.id===l.skuId)?.reason||'超出新类型范围，将移除'}`).join('；')].join('；'),'切换影响确认',{confirmButtonText:'应用切换并移除',cancelButtonText:'取消，保留原内容',closeOnClickModal:false})}work.value.record.scope=copy(next);for(const l of removed)remove(l.skuId);if(updateUrl)await syncUrl();error.value='';return true}catch(e){if(e!=='cancel'&&e!=='close')error.value=String(e);return false}finally{busy.value=false}}
async function changeMode(mode:string){await switchScope({...copy(work.value.record.scope),mode:mode==='group'?'group':'free',groupId:undefined,productTypeIds:mode==='group'?[]:work.value.record.scope.productTypeIds})}
async function selectGroup(id:string){const g=enabledGroups.value.find(g=>g.id===id);if(!g){error.value='权益包已停用或不存在';return}await switchScope({...copy(work.value.record.scope),mode:'group',groupId:g.id,categoryId:g.categoryId,productTypeIds:[...g.productTypeIds]})}
async function selectDevice(key:string){await switchScope(initialScope({...copy(work.value.record.scope),device:deviceFromKey(key)}))}
function openTypes(){pendingScope.value=copy(work.value.record.scope);typesOpen.value=true}
async function applyTypes(){const problem=typesProblem(store.data,pendingScope.value.productTypeIds);if(problem){error.value=problem;return}if(await switchScope(pendingScope.value))typesOpen.value=false}
async function discard(){if(!dirty())return true;try{await ElMessageBox.confirm('当前清单尚有未保存修改，确定切换？','保留或放弃修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});const saved=store.data.benefitSalesLists?.find(s=>s.id===work.value.record.id);if(saved)setRecord(saved);else work.value=emptySale();workingSales.set(actor.value,copy(work.value));return true}catch{return false}}
function setRecord(record:BenefitSale){work.value={record:copy(record),prices:Object.fromEntries(record.lines.map(l=>[l.skuId,l.unitPriceCents===null?'':(l.unitPriceCents/100).toFixed(2)])),saved:''};work.value.saved=stamp();error.value=''}
async function loadRecord(id:string){if(busy.value||!await discard())return;const record=store.data.benefitSalesLists?.find(s=>s.id===id);if(!record){error.value='清单不存在或不可查看';return}setRecord(record);await syncUrl()}
async function newSale(){if(busy.value||!await discard())return;work.value=emptySale();error.value='';await syncUrl()}
async function copyConfirmed(){const old=copy(work.value.record);const q=saleQuery(store.data,old.scope),allowed=new Set(q.candidates.map(c=>c.id));setRecord({...old,id:'',revision:0,status:'draft',snapshot:undefined,createdAt:'',updatedAt:'',lines:old.lines.filter(l=>allowed.has(l.skuId))});work.value.saved='';error.value=old.lines.some(l=>!allowed.has(l.skuId))?'已按当前资料核对，不再合法的商品未复制；历史清单保持不变':'';await syncUrl()}
async function save(status:'draft'|'confirmed'){if(busy.value)return;for(const l of work.value.record.lines)if(priceCents(work.value.prices[l.skuId]||'')===undefined){error.value='报价须为非负金额，最多两位小数';return}busy.value=true;error.value='';const before=stamp();try{const result=await store.saveBundleSale({...copy(work.value.record),lines:pricedLines.value,status},work.value.record.revision,()=>stamp()===before);if(!result.ok){error.value=result.message||'保存失败';return}if('record' in result){setRecord(result.record);await syncUrl();ElMessage.success(status==='confirmed'?'清单已确认':'草稿已保存')}}catch(e){error.value=String(e)}finally{busy.value=false}}
async function maintain(id:string){leavingForMaintenance=true;try{await router.push({path:'/compatibility',query:{tab:'ranges',targetId:id,device:work.value.record.scope.device?.kind==='sku'?work.value.record.scope.device.skuId:undefined,deviceModel:work.value.record.scope.device?.kind==='model'?work.value.record.scope.device.key:undefined,returnTo:route.fullPath}})}finally{leavingForMaintenance=false}}
watch(work,()=>workingSales.set(actor.value,copy(work.value)),{deep:true,flush:'sync'})
watch(actor,()=>{work.value=copy(workingSales.get(actor.value)||emptySale());typesOpen.value=false;error.value='身份已切换，已恢复该身份的独立工作清单'})
onBeforeRouteLeave(async()=>!busy.value&&(leavingForMaintenance||await discard()))
// Every entrance uses the same resolver and the existing scope-impact confirmation.
function entranceDevice(q:LocationQuery):{explicit:boolean;device:SaleScope['device'];message:string}{
 const explicit=['device','deviceModel','model','version','node'].some(k=>q[k]!==undefined)
 if(!explicit)return {explicit:false,device:null,message:''}
 let device:SaleScope['device']=null
 if(typeof q.device==='string'&&q.device){const key=q.device.startsWith('sku:')||q.device.startsWith('model:')?q.device:`sku:${q.device}`;device=deviceFromKey(key)}
 else if(typeof q.deviceModel==='string'&&q.deviceModel)device={kind:'model',key:q.deviceModel}
 else if(typeof q.model==='string'&&typeof q.version==='string'){
  const versions=store.data.specModelVersions.filter(v=>v.templateId===q.model&&v.id===q.version),version=versions.length===1&&versions[0]?.status==='published'?versions[0]:undefined
  const nodes=new Map(version?.nodesSnapshot.map(n=>[n.id,n])),path:{attributeId:string;valueId:string}[]=[],seen=new Set<string>()
  let node=typeof q.node==='string'?nodes.get(q.node):undefined,valid=!q.node||!!node
  while(node){
   if(seen.has(node.id)){valid=false;break}seen.add(node.id)
   if(node.nodeType==='VALUE')path.unshift({attributeId:nodes.get(node.parentId||'')?.attributeId||node.attributeId,valueId:node.valueId})
   if(node.parentId&&!nodes.has(node.parentId)){valid=false;break}node=node.parentId?nodes.get(node.parentId):undefined
  }
  if(version&&nodes.size!==version.nodesSnapshot.length)valid=false
  const options=version&&valid?devices.value.models.filter(m=>m.host.productModelId===q.model&&m.versionIds.includes(version.id)&&path.slice(0,m.host.steps.length).every((step,i)=>m.host.steps[i]?.attributeId===step.attributeId&&m.host.steps[i]?.valueId===step.valueId)):[]
  if(options.length===1)device={kind:'model',key:options[0]!.key}
 }
 const key=deviceKey(device)
 if(device?.kind==='sku'&&!devices.value.skus.some(s=>`sku:${s.id}`===key))device=null
 if(device?.kind==='model'&&!devices.value.models.some(m=>`model:${m.key}`===key))device=null
 return {explicit,device,message:device?'':'来源无法准确识别设备，请明确选择本次使用设备。'}
}
async function applyEntrance(q:LocationQuery){
 if(busy.value)return false
 if(q.sale&&q.sale!==work.value.record.id){const record=store.data.benefitSalesLists?.find(s=>s.id===q.sale);if(!record){error.value='清单不存在或不可查看';return false}if(!await discard())return false;setRecord(record)}
 // Confirmed records remain historical, regardless of any extra URL preview parameters.
 if(readonly.value&&q.sale)return true
 const next=copy(work.value.record.scope),source=entranceDevice(q)
 if(q.group&&q.group!==next.groupId){const g=enabledGroups.value.find(g=>g.id===q.group);if(!g){error.value='指定权益包已停用或不存在，请选择其他包或自由组合';return false}Object.assign(next,{mode:'group',groupId:g.id,categoryId:g.categoryId,productTypeIds:[...g.productTypeIds]})}
 if(source.explicit)next.device=source.device
 Object.assign(next,initialScope(next))
 if(JSON.stringify(next)!==JSON.stringify(work.value.record.scope)){
  if(readonly.value){work.value=emptySale();work.value.record.scope=next}
  else if(!await switchScope(next,false))return false
 }
 error.value=source.message
 return true
}
onBeforeRouteUpdate(async to=>{if(internal)return true;const previous=copy(work.value);if(await applyEntrance(to.query))return true;work.value=previous;return false})
function beforeUnload(e:BeforeUnloadEvent){if(busy.value||dirty()){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
watch(()=>route.fullPath,()=>{if(route.path==='/benefits/shopping')work.value.query=copy(route.query)})
onMounted(async()=>{
 const previous=copy(work.value)
 if(await applyEntrance(route.query))work.value.query=copy(route.query)
 else {work.value=previous;if(previous.query){internal=true;try{await router.replace({path:route.path,query:previous.query})}finally{internal=false}}else await syncUrl()}
})

</script>
